import React from "react";

function Home() {

  const products = [
    {
      _id: 1,
      name: "Nike Air Max",
      price: 4999,
      image: "https://images.unsplash.com/photo-1542291026-7eec264c27ff"
    },
    {
      _id: 2,
      name: "Oversized T-Shirt",
      price: 1299,
      image: "https://images.unsplash.com/photo-1521572163474-6864f9cf17ab"
    },
    {
      _id: 3,
      name: "Wireless Headphones",
      price: 2999,
      image: "https://images.unsplash.com/photo-1505740420928-5e560c06d30e"
    },
    {
      _id: 4,
      name: "Smart Watch",
      price: 5999,
      image: "https://images.unsplash.com/photo-1517430816045-df4b7de11d1d"
    },
    {
      _id: 5,
      name: "Gaming Mouse",
      price: 1499,
      image: "https://images.unsplash.com/photo-1527814050087-3793815479db"
    },
    {
      _id: 6,
      name: "Backpack",
      price: 1999,
      image: "https://images.unsplash.com/photo-1581605405669-fcdf81165afa"
    },
    {
      _id: 7,
      name: "Sneakers",
      price: 3499,
      image: "https://images.unsplash.com/photo-1549298916-b41d501d3772"
    },
    {
      _id: 8,
      name: "Sunglasses",
      price: 899,
      image: "https://images.unsplash.com/photo-1511499767150-a48a237f0083"
    }
  ];

  return (
    <div style={{
      background: "#f3f4f6",
      minHeight: "100vh",
      fontFamily: "Arial"
    }}>

      {/* Navbar */}
      <div style={{
        background: "#111827",
        color: "white",
        padding: "20px 40px",
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        position: "sticky",
        top: "0"
      }}>
        <h1>🛒 ShopEasy</h1>

        <div style={{
          display: "flex",
          gap: "25px",
          fontSize: "18px"
        }}>
          <span>Home</span>
          <span>Products</span>
          <span>Cart</span>
        </div>
      </div>

      {/* Hero Section */}
      <div style={{
        background: "linear-gradient(to right, #111827, #1f2937)",
        color: "white",
        padding: "70px 40px",
        textAlign: "center"
      }}>
        <h1 style={{
          fontSize: "50px",
          marginBottom: "20px"
        }}>
          Welcome to ShopEasy
        </h1>

        <p style={{
          fontSize: "20px",
          color: "#d1d5db"
        }}>
          Buy trendy fashion, gadgets & accessories at best prices.
        </p>

        <button style={{
          marginTop: "30px",
          padding: "14px 28px",
          background: "#2563eb",
          border: "none",
          color: "white",
          borderRadius: "8px",
          fontSize: "18px",
          cursor: "pointer"
        }}>
          Shop Now
        </button>
      </div>

      {/* Product Section */}
      <div style={{
        padding: "50px"
      }}>

        <h2 style={{
          textAlign: "center",
          marginBottom: "40px",
          fontSize: "38px",
          color: "#111827"
        }}>
          Featured Products
        </h2>

        <div style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit,minmax(250px,1fr))",
          gap: "30px"
        }}>

          {products.map((p) => (

            <div
              key={p._id}
              style={{
                background: "white",
                borderRadius: "15px",
                overflow: "hidden",
                boxShadow: "0 4px 12px rgba(0,0,0,0.15)",
                transition: "0.3s"
              }}
            >

              <img
                src={p.image}
                alt={p.name}
                style={{
                  width: "100%",
                  height: "240px",
                  objectFit: "cover"
                }}
              />

              <div style={{
                padding: "20px"
              }}>

                <h3 style={{
                  fontSize: "22px",
                  marginBottom: "10px",
                  color: "#111827"
                }}>
                  {p.name}
                </h3>

                <p style={{
                  fontSize: "20px",
                  color: "#16a34a",
                  fontWeight: "bold"
                }}>
                  ₹{p.price}
                </p>

                <button style={{
                  marginTop: "15px",
                  width: "100%",
                  padding: "12px",
                  background: "#111827",
                  color: "white",
                  border: "none",
                  borderRadius: "8px",
                  fontSize: "16px",
                  cursor: "pointer"
                }}>
                  Add to Cart
                </button>

              </div>

            </div>

          ))}

        </div>

      </div>

      {/* Footer */}
      <div style={{
        background: "#111827",
        color: "white",
        textAlign: "center",
        padding: "20px",
        marginTop: "50px"
      }}>
        <p>© 2026 ShopEasy | MERN E-Commerce Project</p>
      </div>

    </div>
  );
}

export default Home;
